const PHONE_RULES = [
  ['IN', /^\+91[6-9]\d{9}$/, '91', 12], ['US', /^\+1\d{10}$/, '1', 11], ['GB', /^\+447\d{9}$/, '44', 12],
  ['AE', /^\+9715\d{8}$/, '971', 12], ['SG', /^\+65[89]\d{7}$/, '65', 10],
];
