  if (text.startsWith('+')) cand = `+${digits}`;
  else if (digits.startsWith('00')) cand = `+${digits.slice(2)}`;
  else cand = nationalToE164(digits, COUNTRY_ISO[country] || '');
  return cand && validE164(cand) ? [cand, 'ok'] : [null, `unrecognised format (${text})`];
}
